// @od-design/preview styles — import once in the host app:
//   import '@od-design/preview/styles';
//
// upstream.scoped.css is Open Design's stylesheet, trimmed to the selectors the
// preview renders and scoped to `.odp-scope` (both generated by
// scripts/sync-upstream.mjs → scripts/lib/scope-css.mjs), so it never touches
// the host app: no global resets, design tokens live on the library's root
// elements. app.scss holds this library's own (class-only) rules on top.
import './upstream.scoped.css';
import './app.scss';
